/* Shared project-cover renderer: the editor and public site use the same layout. */
(function(root){
const types={watch:'Smartwatch',browser:'Browser',terminal:'Terminal',travel:'Travel browser',phone:'Phone'};
const presets={
watch:{template:'watch',eyebrow:'NEWS, WITH A NEW RHYTHM.',headline:'Listen.\nLearn.\nKeep going.',footer:'ANDROID + WEAR OS + WEB',windowLabel:'your next idea',rotation:12,frameSize:100,frameX:0,frameY:0,corners:10,shadow:25,imageZoom:100,imageX:50,imageY:50,fit:'cover',terminalText:'$ your next idea\n✓ Something worth building.'},
browser:{template:'browser',eyebrow:'A LITTLE SPACE FOR BIG IDEAS.',headline:'Less scattered.\nMore creative.',footer:'REFERENCE → SCRIPT → STORYBOARD',windowLabel:'creator’s workspace',rotation:-4,frameSize:100,frameX:0,frameY:0,corners:8,shadow:20,imageZoom:100,imageX:50,imageY:0,fit:'cover',terminalText:'$ your next idea\n✓ Something worth building.'},
terminal:{template:'terminal',eyebrow:'LESS SETUP. MORE BUILDING.',headline:'Ready, set,\ncreate.',footer:'PYTHON CLI / REACT SCAFFOLDING',windowLabel:'your next project',rotation:-3,frameSize:100,frameX:0,frameY:0,corners:8,shadow:28,imageZoom:100,imageX:50,imageY:50,fit:'contain',terminalText:'~ belazywithreact create my-app\n\n✓ React + TypeScript\n✓ Your tools, already connected\n↳ Time to make something.'},
travel:{template:'travel',eyebrow:'FROM “WE SHOULD GO” TO “LET’S GO”.',headline:'Good company.\nBetter plans.',footer:'PLAN / COORDINATE / EXPLORE',windowLabel:'that one day',rotation:4,frameSize:100,frameX:0,frameY:0,corners:8,shadow:20,imageZoom:100,imageX:50,imageY:0,fit:'cover',terminalText:'$ your next idea\n✓ Something worth building.'},
phone:{template:'phone',eyebrow:'MADE FOR LIFE ON THE GO.',headline:'Small screen.\nBig possibilities.',footer:'A LITTLE WORLD IN YOUR POCKET',windowLabel:'mobile experience',rotation:9,frameSize:100,frameX:0,frameY:0,corners:12,shadow:30,imageZoom:100,imageX:50,imageY:0,fit:'cover',terminalText:'$ your next idea\n✓ Something worth building.'}
};
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const clamp=(value,min,max,fallback)=>{const n=Number(value);return Number.isFinite(n)?Math.min(max,Math.max(min,n)):fallback};
function config(project={}){const saved=project.cover_layout&&typeof project.cover_layout==='object'&&!Array.isArray(project.cover_layout)?project.cover_layout:{};const legacy={news:'watch',creator:'browser',cli:'terminal',trip:'travel'};const type=Object.hasOwn(types,saved.template)?saved.template:Object.hasOwn(legacy,project.id)?legacy[project.id]:'browser';const p={...presets[type],...saved,template:type};for(const key of ['eyebrow','headline','footer','windowLabel','terminalText'])p[key]=String(p[key]??'').slice(0,key==='terminalText'?1500:300);for(const [key,min,max] of [['rotation',-15,15],['frameSize',70,130],['frameX',-25,25],['frameY',-20,20],['corners',0,30],['shadow',0,60],['imageZoom',100,220],['imageX',0,100],['imageY',0,100]])p[key]=clamp(p[key],min,max,presets[type][key]);p.fit=p.fit==='contain'?'contain':'cover';return p;}
function imageURL(value){if(!value)return '';try{const base=typeof location!=='undefined'?location.origin:'https://portfolio.invalid';const url=new URL(value,base);if(url.protocol==='https:'||url.origin===base)return url.href}catch{}return '';}
function render(project={}){const p=config(project),url=imageURL(project.cover_url),color=['lilac','mint','peach','yellow'].includes(project.cover_color)?project.cover_color:'lilac';const lines=p.headline.split('\n').filter(Boolean).slice(0,3);const headline=lines.map((line,i)=>`<span${i===lines.length-1&&p.template!=='watch'?' class="cover-italic"':''}>${esc(line)}</span>`).join('');const image=url?`<img class="template-image" src="${esc(url)}" alt="${esc(project.title||'Project')} screenshot" loading="lazy" style="object-fit:${p.fit};object-position:${p.imageX}% ${p.imageY}%;transform:scale(${p.imageZoom/100})">`:'<span class="template-empty" aria-hidden="true">✳</span>';const bar=`<div class="template-window-bar" aria-hidden="true"><span>● ● ●</span><small>${esc(p.windowLabel)}</small></div>`;const screen=p.template==='terminal'&&!url?`<pre class="template-terminal-text">${esc(p.terminalText)}</pre>`:image;let frame;
if(p.template==='watch')frame=`<div class="template-frame template-watch"><div class="watch-band" aria-hidden="true"></div><div class="device-screen watch-screen">${image}</div><i class="watch-crown" aria-hidden="true"></i></div>`;
else if(p.template==='phone')frame=`<div class="template-frame template-phone"><div class="device-screen phone-screen">${image}</div><i class="phone-island" aria-hidden="true"></i><i class="phone-home" aria-hidden="true"></i><i class="phone-side" aria-hidden="true"></i></div>`;
else frame=`<div class="template-frame template-browser ${p.template==='terminal'?'is-terminal':''}">${bar}<div class="device-screen browser-screen">${screen}</div></div>`;
return `<div class="cover-canvas template-${p.template} color-${color}" style="--frame-rotation:${p.rotation}deg;--frame-size:${p.frameSize/100};--frame-x:${p.frameX}cqw;--frame-y:${p.frameY}cqw;--frame-radius:${p.corners}px;--frame-shadow:${p.shadow/100};"><span class="template-eyebrow">${esc(p.eyebrow)}</span><div class="template-headline">${headline}</div>${frame}${p.template==='watch'?'<div class="template-wave" aria-hidden="true">'+Array.from({length:11},()=>'<i></i>').join('')+'</div>':''}${p.template==='travel'?'<span class="template-sun" aria-hidden="true">☀</span>':''}${p.template==='terminal'?'<span class="template-command" aria-hidden="true">↳</span>':''}${p.template==='phone'?'<span class="template-phone-note" aria-hidden="true">built to go places.</span>':''}<span class="template-footer">${esc(p.footer)}</span><span class="template-arrow" aria-hidden="true">↗</span></div>`;
}
const api={types,presets,config,render,imageURL};if(typeof module==='object'&&module.exports)module.exports=api;else root.ProjectCovers=api;
})(typeof window==='undefined'?globalThis:window);
